-- STATUS: APPLIED LIVE 2026-11-27 on owner OK (targeting as migration checklist_targeting_plant_vehicle_split; drafts as checklist_draft_workshop_housekeeping and checklist_draft_workshop_tools_check). Verified: WHK 43 fields, WTC 46 fields, both draft v1.
-- 1. Snapshot every template's assignee_roles/status into _bak.checklist_template_targeting_20261127.
-- 2. Owner split: plant trades vs vehicle trades.
--    ICP, CHL, CLG, GSR, BPD -> plant trades + Workshop Supervisor + Maintenance Supervisor.
--    ACP -> the same + Tyre Man (Tyre Men use the air compressors).
--    WDC -> vehicle trades + Tyre Man + Workshop Supervisor + Maintenance Supervisor.
--    FTM unchanged (Driver + Workshop Supervisor).
-- 3. Two DRAFT templates (not published): Workshop Housekeeping Checklist (WHK) and
--    Workshop Tools Check (WTC). Weekly, two-stage approval, all trades + helpers + Tyre Man.
-- NOT done on purpose: DWC and DVC are the Tyre Pulse Demo Fleet org's templates (Play
-- reviewer account demo.manager, 3 demo submissions). Company A users never see them, so
-- they are not a production duplicate; archiving them would empty the reviewer demo.
-- PMC kept: imported from the owner's spreadsheet, 197 fields, a real submission on GN147.
-- VERIFY: select doc_prefix, assignee_roles from checklist_templates order by 1;
--         select doc_prefix, status from checklist_templates where doc_prefix in ('WHK','WTC');
-- ROLLBACK:
--   update checklist_templates t set assignee_roles=b.assignee_roles
--     from _bak.checklist_template_targeting_20261127 b where b.id=t.id;
--   update checklist_templates set status='archived' where doc_prefix in ('WHK','WTC');
create table if not exists _bak.checklist_template_targeting_20261127 as
  select id, doc_prefix, name, status, assignee_roles, now() as snapshotted_at
    from public.checklist_templates;

update public.checklist_templates set assignee_roles = array['Assistant Plant Mechanic','Helper Ice Plant','Helper Plant','Ice Plant Technician','Maintenance Supervisor','Plant Electrician','Plant Mechanic','Senior Plant & Chiller Technician','Senior Plant Technician','Workshop Supervisor']::text[]
 where doc_prefix in ('ICP','CHL','CLG','GSR','BPD') and organisation_id='00000000-0000-0000-0000-000000000001';
update public.checklist_templates set assignee_roles = array['Assistant Plant Mechanic','Helper Ice Plant','Helper Plant','Ice Plant Technician','Maintenance Supervisor','Plant Electrician','Plant Mechanic','Senior Plant & Chiller Technician','Senior Plant Technician','Tyre Man','Workshop Supervisor']::text[]
 where doc_prefix = 'ACP' and organisation_id='00000000-0000-0000-0000-000000000001';
update public.checklist_templates set assignee_roles = array['Auto Electrician','Concrete Breaker','Denter','Diesel Mechanic','Electrician','Helper PMV','Helper Workshop','Hydraulic Mechanic','Maintenance Supervisor','Mechanic','Painter','Senior Technician','Tyre Man','Welder','Welder Cum Fabricator','Workshop Supervisor']::text[]
 where doc_prefix = 'WDC' and organisation_id='00000000-0000-0000-0000-000000000001';

insert into public.checklist_templates
  (organisation_id,country,name,description,category,icon,status,version,require_signature,require_approval,
   require_area_manager,fields,scored,name_i18n,description_i18n,option_sets,assignee_roles,doc_prefix,
   min_interval_days,form_ref,form_revision,form_owner,review_interval_months)
select '00000000-0000-0000-0000-000000000001',null,'Workshop Housekeeping Checklist',$d$Weekly workshop housekeeping audit (5S and HSE): walkways, spills and drip trays, waste oil and scrap, tyre stacking, tool boards, chemicals and gas cylinders, fire and first aid, electrical panels, lifting gear, PPE and the washing bay. Every Not OK needs a remark. Signed off by a supervisor, closed by the area manager. Nothing closes while an item is still Not OK.$d$,'Safety','safety','draft',1,true,true,
