   $j${"ar": "تدقيق أسبوعي لنظافة وترتيب الورشة (5S والسلامة). كل بند غير سليم يحتاج ملاحظة. يعتمده المشرف ويغلقه مدير المنطقة.", "hi": "साप्ताहिक वर्कशॉप हाउसकीपिंग ऑडिट (5S और सुरक्षा). हर ठीक नहीं बिंदु पर टिप्पणी जरूरी. सुपरवाइजर स्वीकृत करता है, एरिया मैनेजर बंद करता है.", "ur": "ہفتہ وار ورکشاپ ہاؤس کیپنگ آڈٹ (5S اور حفاظت)۔ ہر ٹھیک نہیں بند پر ریمارک ضروری۔ سپروائزر منظوری دیتا ہے، ایریا مینیجر بند کرتا ہے۔"}$j$::jsonb,$j${"legend": {"options": ["OK", "Not OK", "Not applicable", "Corrected on the spot"], "i18n": {"ar": ["سليم", "غير سليم", "لا ينطبق", "تم التصحيح فورا"], "hi": ["ठीक", "ठीक नहीं", "लागू नहीं", "मौके पर ठीक किया"], "ur": ["ٹھیک", "ٹھیک نہیں", "لاگو نہیں", "موقع پر درست کیا"]}, "meta": [{"icon": "ok", "tone": "good", "value": "OK", "meaning": "Checked and in order."}, {"icon": "fault", "tone": "bad", "value": "Not OK", "meaning": "A problem is present and has NOT been put right. Say what is wrong and add a photo."}, {"icon": "na", "tone": "muted", "value": "Not applicable", "meaning": "This area or item is not present here."}, {"icon": "repair", "tone": "fixed", "value": "Corrected on the spot", "meaning": "The problem was found and fixed during this check."}], "blocking": ["Not OK"], "require_note": ["Not OK"]}}$j$::jsonb,array['Assistant Plant Mechanic','Auto Electrician','Concrete Breaker','Denter','Diesel Mechanic','Electrician','Helper Ice Plant','Helper PMV','Helper Plant','Helper Workshop','Hydraulic Mechanic','Ice Plant Technician','Mechanic','Painter','Plant Electrician','Plant Mechanic','Senior Plant & Chiller Technician','Senior Plant Technician','Senior Technician','Tyre Man','Welder','Welder Cum Fabricator']::text[],'WHK',
   7,'TP-WHK','v1','Maintenance Department',12
