اچھی حالت میں"}, "options": ["OK", "Not OK", "Not applicable", "Corrected on the spot"], "options_ref": "legend", "required": true, "allow_note": true, "allow_photo": true, "allow_gallery": true, "require_note_when": ["Not OK"]}, {"id": "f_tc_3", "type": "select", "label": "Screwdrivers and pliers, insulation undamaged", "labels": {"ar": "المفكات والزرادي بعزل سليم", "hi": "पेचकस और प्लास, इंसुलेशन सही", "ur": "اسکرو ڈرائیور اور پلاس، انسولیشن درست"}, "options": ["OK", "Not OK", "Not applicable", "Corrected on the spot"], "options_ref": "legend", "required": true, "allow_note": true, "allow_photo": true, "allow_gallery": true, "require_note_when": ["Not OK"]}, {"id": "f_tc_4", "type": "select", "label": "Hammer and mallet heads secure", "labels": {"ar": "رؤوس المطارق ثابتة", "hi": "हथौड़े के सिर मजबूती से लगे", "ur": "ہتھوڑے کے سر مضبوطی سے لگے"}, "options": ["OK", "Not OK", "Not applicable", "Corrected on the spot"], "options_ref": "legend", "required": true, "allow_note": true, "allow_photo": true, "allow_gallery": true, "require_note_when": ["Not OK"]}, {"id": "f_tc_s3", "type": "section", "label": "3. Power tools", "labels": {"ar": "3. الأدوات الكهربائية", "hi": "3. पावर टूल", "ur": "3. پاور ٹول"}}, {"id": "f_tc_5", "type": "select", "label": "Cable and plug undamaged", "labels": {"ar": "الكابل والقابس سليمان", "hi": "केबल और प्लग सही", "ur": "کیبل اور پلگ درست"}, "options": ["OK", "Not OK", "Not applicable", "Corrected on the spot"], "options_ref": "legend", "required": true, "allow_note": true, "allow_photo": true, "allow_gallery": true, "require_note_when": ["Not OK"]}, {"id": "f_tc_6", "type": "select", "label": "Guards fitted and working", "labels": {"ar": "الواقيات مركبة وتعمل", "hi": "गार्ड लगे और काम कर रहे", "ur": "گارڈ لگے اور کام کر رہے"}, "options": ["OK", "Not OK", "Not applicable", "Corrected on the spot"], "options_ref": "legend", "required": true, "allow_note": true, "allow_photo": true, "allow_gallery": true, "require_note_when": ["Not OK"]}, {"