   $j${"ar": "فحص أسبوعي لأدوات الورشة حتى لا تكون هناك أداة مفقودة أو غير آمنة. أي أداة مفقودة أو تالفة تُسجل مع صورة. يعتمده المشرف ويغلقه مدير المنطقة.", "hi": "साप्ताहिक वर्कशॉप औजार जांच ताकि कोई औजार गायब या असुरक्षित न हो. गायब या खराब औजार फोटो के साथ दर्ज करें. सुपरवाइजर स्वीकृत करता है, एरिया मैनेजर बंद करता है.", "ur": "ہفتہ وار ورکشاپ اوزار چیک تاکہ کوئی اوزار گم یا غیر محفوظ نہ ہو۔ گم یا خراب اوزار تصویر کے ساتھ درج کریں۔ سپروائزر منظوری دیتا ہے، ایریا مینیجر بند کرتا ہے۔"}$j$::jsonb,$j${"legend": {"options": ["OK", "Not OK", "Not applicable", "Corrected on the spot"], "i18n": {"ar": ["سليم", "غير سليم", "لا ينطبق", "تم التصحيح فورا"], "hi": ["ठीक", "ठीक नहीं", "लागू नहीं", "मौके पर ठीक किया"], "ur": ["ٹھیک", "ٹھیک نہیں", "لاگو نہیں", "موقع پر درست کیا"]}, "meta": [{"icon": "ok", "tone": "good", "value": "OK", "meaning": "Checked and in order."}, {"icon": "fault", "tone": "bad", "value": "Not OK", "meaning": "A problem is present and has NOT been put right. Say what is wrong and add a photo."}, {"icon": "na", "tone": "muted", "value": "Not applicable", "meaning": "This area or item is not present here."}, {"icon": "repair", "tone": "fixed", "value": "Corrected on the spot", "meaning": "The problem was found and fixed during this check."}], "blocking": ["Not OK"], "require_note": ["Not OK"]}}$j$::jsonb,array['Assistant Plant Mechanic','Auto Electrician','Concrete Breaker','Denter','Diesel Mechanic','Electrician','Helper Ice Plant','Helper PMV','Helper Plant','Helper Workshop','Hydraulic Mechanic','Ice Plant Technician','Mechanic','Painter','Plant Electrician','Plant Mechanic','Senior Plant & Chiller Technician','Senior Plant Technician','Senior Technician','Tyre Man','Welder','Welder Cum Fabricator']::text[],'WTC',
